import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let xs = [1, 2, 3, 4]
    let ys = xs.iterator().collect()
    for x in ys { io.println("e ${x}") }

    let n = ys.iterator().count()
    if n == 4 { io.println("count-ok") } else { io.println("count-bad") }

    let s = ys.iterator().fold(0, |acc, x| acc + x)
    if s == 10 { io.println("fold-ok") } else { io.println("fold-bad") }

    let zs = ys.iterator().collect()
    let f = zs.iterator().find(|x| x > 3)
    match f {
        Some(v) => { if v == 4 { io.println("refind-ok") } else { io.println("refind-bad") } }
        None => { io.println("refind-none") }
    }

    let es: List<Int64> = []
    let ws = es.iterator().collect()
    let n3 = ws.iterator().count()
    if n3 == 0 { io.println("empty-ok") } else { io.println("empty-bad") }

    return Ok(())
}
